#include "rpg/pve_visual.hpp"
#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;using namespace rpg::presentation;
void check(bool ok,const char* why){if(!ok){throw std::runtime_error(why);}}
void preflight(){PveVisualSession s;check(s.submit(0,1,"ECO-1").accepted(),"opening");const auto before=s.observation();const auto stale=action_feedback(s.submit(0,1,"ECO-1"));check(!stale.applied&&!stale.retry_target&&stale.summary.find("avancou")!=std::string::npos,"stale cannot look accepted");const auto other=action_feedback(s.submit(1,1,"ECO-1"));check(!other.applied&&other.summary.find("Aguarde")!=std::string::npos&&s.observation()==before,"not player turn, no mutation");}
void retry(){PveVisualSession s;const auto before=s.observation();auto f=action_feedback(s.submit(0,1,"absent"));check(!f.applied&&f.retry_target&&f.summary.find("Alvo")!=std::string::npos&&s.observation()==before,"invalid target preserved as retry");check(s.submit(0,1,"ECO-1").accepted(),"retry works without spent turn");}
void passive(){PveVisualSession s;auto f=action_feedback(s.submit(0,2,"ECO-1"));check(!f.applied&&!f.retry_target&&s.state().revision==0,"passive rejected without spending");}
void success(){PveVisualSession s;const auto result=s.submit(0,1,"ECO-1");const auto before=s.observation();auto f=action_feedback(result);check(f.applied&&f.tone==FeedbackTone::Success&&!f.details.empty()&&f.summary.find("PV -")!=std::string::npos,"authoritative damage feedback");for(int i=0;i<30;++i){static_cast<void>(action_feedback(result));}check(s.observation()==before,"formatting never advances battle");}
void shield(){auto setup=team_reference_setup();for(auto& d:setup.roster){d.speed=1;}setup.roster[0].speed=200;VisualSession s(setup);const auto f=action_feedback(s.submit(0,3,"A1"));check(f.applied&&f.summary.find("escudo")!=std::string::npos,"shield is not reported as attack");}
void defensive_outcomes(){for(const auto contact:{resolution::Contact::Miss,resolution::Contact::Blocked,resolution::Contact::Invincible}){VisualResult r;Event e{EventType::Attack,"A","B",0};resolution::HitReport hit;hit.outcome.contact=contact;e.hit=hit;r.action.events.push_back(e);auto f=action_feedback(r);check(f.applied&&f.summary.find("PV -")==std::string::npos,"zero outcomes not ordinary damage");}}
void absorbed(){VisualResult r;Event e{EventType::Attack,"A","B",0};resolution::HitReport hit;hit.absorbed=10;hit.health_damage=0;e.hit=hit;r.action.events.push_back(e);const auto f=action_feedback(r);check(f.applied&&f.summary.find("escudo absorveu 10")!=std::string::npos&&f.summary.find("PV -0")!=std::string::npos,"shield and HP stay separate");}
void cap(){VisualResult r;for(int i=0;i<100;++i){r.action.events.push_back({EventType::Attack,"A","B",i});}const auto f=action_feedback(r,3);check(f.details.size()==5&&f.details.back().find("omitidos")!=std::string::npos,"bounded event summary");check(action_feedback(r,0).details.size()==3&&action_feedback(r,1000).details.size()==34,"bounds validated");}
void stops(){VisualResult r;r.error=VisualError::SafetyStop;auto f=action_feedback(r);check(!f.applied&&f.tone==FeedbackTone::Error&&!f.retry_target,"safety stop clear");r.error=VisualError::Finished;f=action_feedback(r);check(!f.applied&&f.summary.find("terminou")!=std::string::npos,"finished cannot look accepted");}
void no_false_success(){VisualResult r;r.error=VisualError::CoreRejected;check(!action_feedback(r).applied,"empty core rejection not accepted");r.error=VisualError::None;r.action.error=ActionError::SkillOnCooldown;const auto f=action_feedback(r);check(!f.applied&&f.summary.find("recarga")!=std::string::npos,"inconsistent wrapper error remains refusal");}
void all_labs(){SequentialVisualSession seq;SharedVisualSession shared;WaveVisualSession wave;check(action_feedback(seq.submit(0,1,"CHEFE-SEQ")).applied,"sequence shares feedback");check(action_feedback(shared.submit(0,1,"CHEFE-PAR")).applied,"fronts share feedback");check(action_feedback(wave.submit(0,1,"ECO-1")).applied,"wave shares feedback");}
void defeat_identity(){auto d=ritual_lab_definition();d.roster[1].max_health=1;d.roster[1].stats.block=0;PveVisualSession s(d);const auto f=action_feedback(s.submit(0,1,"ECO-1"));check(f.applied&&std::ranges::any_of(f.details,[](const std::string& line){return line.find("ECO-1")!=std::string::npos&&line.find("derrotado")!=std::string::npos;}),"defeated event uses owner identity");}
int main(){try{preflight();retry();passive();success();shield();defensive_outcomes();absorbed();cap();stops();no_false_success();all_labs();defeat_identity();std::cout<<"REG_FEEDBACK_TESTS_RESULT passed=12 total=12\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}